INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (570, 1, 'dig 응답의 상태와 답한 서버', '`/tmp/dig_full.log` 는 `dig www.example.com` 을 실행한 결과를 저장한 것입니다. 헤더의 `status:` 는 질의가 어떻게 끝났는지 보여 주고, 맨 아래 `SERVER:` 는 실제로 답한 DNS 서버입니다. 두 값을 저장하세요. (값만)
- `/tmp/status.txt` : `status:` 값
- `/tmp/server.txt` : 답한 서버의 IP 주소', '헤더 줄과 맨 아래 `SERVER:` 줄에서 값을 찾아 필요한 부분만 잘라 내세요.', 'cat /tmp/dig_full.log
grep -o ''status: [A-Z]*'' /tmp/dig_full.log | cut -d'' '' -f2 > /tmp/status.txt
grep ''SERVER:'' /tmp/dig_full.log | cut -d'' '' -f3 | cut -d''#'' -f1 > /tmp/server.txt
cat /tmp/status.txt /tmp/server.txt

# NOERROR 는 정상 응답. SERVER 는 resolv.conf 의 nameserver 중 실제로 답한 서버다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.conf\\ngrep -v ''api.example.com'' /etc/hosts > /tmp/hosts.new; cat /tmp/hosts.new > /etc/hosts; rm -f /tmp/hosts.new\\necho ''192.0.2.77 api.example.com'' >> /etc/hosts\\ncat > /tmp/dig_full.log <<''EOF''\\n; <<>> DiG 9.18.1 <<>> www.example.com\\n;; global options: +cmd\\n;; Got answer:\\n;; ->>HEADER<<- opcode: QUERY, status: NOERROR, id: 41234\\n;; flags: qr rd ra; QUERY: 1, ANSWER: 2, AUTHORITY: 0, ADDITIONAL: 1\\n\\n;; QUESTION SECTION:\\n;www.example.com.               IN      A\\n\\n;; ANSWER SECTION:\\nwww.example.com.        300     IN      A       192.0.2.11\\nwww.example.com.        300     IN      A       192.0.2.10\\n\\n;; Query time: 23 msec\\n;; SERVER: 192.0.2.53#53(192.0.2.53) (UDP)\\n;; WHEN: Fri Nov 20 10:00:00 KST 2026\\n;; MSG SIZE  rcvd: 76\\nEOF\\ncat > /tmp/dig_nx.log <<''EOF''\\n; <<>> DiG 9.18.1 <<>> missing.example.com\\n;; Got answer:\\n;; ->>HEADER<<- opcode: QUERY, status: NXDOMAIN, id: 5821\\n;; flags: qr rd ra; QUERY: 1, ANSWER: 0, AUTHORITY: 1, ADDITIONAL: 1\\n\\n;; QUESTION SECTION:\\n;missing.example.com.           IN      A\\n\\n;; AUTHORITY SECTION:\\nexample.com.            900     IN      SOA     ns1.example.net. admin.example.net. 2026112001 7200 900 1209600 86400\\n\\n;; Query time: 31 msec\\n;; SERVER: 192.0.2.53#53(192.0.2.53) (UDP)\\nEOF\\ncat > /tmp/dig_t1.log <<''EOF''\\n;; ANSWER SECTION:\\nwww.example.com.        300     IN      A       192.0.2.10\\n;; Query time: 41 msec\\n;; WHEN: Fri Nov 20 10:00:00 KST 2026\\nEOF\\ncat > /tmp/dig_t2.log <<''EOF''\\n;; ANSWER SECTION:\\nwww.example.com.        240     IN      A       192.0.2.10\\n;; Query time: 0 msec\\n;; WHEN: Fri Nov 20 10:01:00 KST 2026\\nEOF\\ncat > /tmp/dig_trace.log <<''EOF''\\n.                       518400  IN      NS      a.root.example.net.\\n;; Received 239 bytes from 192.0.2.53#53(192.0.2.53) in 1 ms\\n\\ncom.                    172800  IN      NS      a.tld.example.net.\\n;; Received 1170 bytes from 198.51.100.4#53(a.root.example.net) in 12 ms\\n\\nexample.com.            172800  IN      NS      ns1.example.net.\\nexample.com.            172800  IN      NS      ns2.example.net.\\n;; Received 800 bytes from 198.51.100.30#53(a.tld.example.net) in 20 ms\\n\\nwww.example.com.        300     IN      A       192.0.2.10\\n;; Received 60 bytes from 203.0.113.53#53(ns1.example.net) in 25 ms\\nEOF\\ncat > /tmp/resolv_sample.conf <<''EOF''\\nsearch corp.example.com lab.example.com\\nnameserver 192.0.2.53\\nnameserver 192.0.2.54\\noptions ndots:5 timeout:2 attempts:3\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/status.txt)\\" = NOERROR ] ) && ( [ \\"$(cat /tmp/server.txt)\\" = 192.0.2.53 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "상태가 NOERROR 다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/status.txt)\\" = NOERROR ]"]}, {"label": "서버가 192.0.2.53 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/server.txt)\\" = 192.0.2.53 ]"]}]', '[{"title": "dig 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/dig.1.html"}, {"title": "resolv.conf 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/resolv.conf.5.html"}]'),
  (570, 2, '답 레코드의 주소 뽑기', '`/tmp/dig_full.log` 의 `ANSWER SECTION` 에는 이 이름이 가리키는 A 레코드(IPv4 주소)가 있습니다. 주소만 **오름차순으로 정렬해 한 줄에 하나씩** `/tmp/ips.txt` 에 저장하세요. (`dig +short` 가 보여 주는 것과 같은 내용입니다)', '답 레코드 줄은 이름·TTL·IN·타입·값으로 이어집니다. 타입이 A 인 줄의 마지막 칸을 뽑아 정렬하세요.', 'awk ''$3 ~ /^IN$/ && $4 ~ /^A$/ {print $NF}'' /tmp/dig_full.log | sort > /tmp/ips.txt
cat /tmp/ips.txt

# 같은 이름에 주소가 둘이면 클라이언트는 보통 둘 중 하나(순서는 서버가 돌려 가며 바꿈)를 쓴다. 이것이 DNS 라운드 로빈이다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.conf\\ngrep -v ''api.example.com'' /etc/hosts > /tmp/hosts.new; cat /tmp/hosts.new > /etc/hosts; rm -f /tmp/hosts.new\\necho ''192.0.2.77 api.example.com'' >> /etc/hosts\\ncat > /tmp/dig_full.log <<''EOF''\\n; <<>> DiG 9.18.1 <<>> www.example.com\\n;; global options: +cmd\\n;; Got answer:\\n;; ->>HEADER<<- opcode: QUERY, status: NOERROR, id: 41234\\n;; flags: qr rd ra; QUERY: 1, ANSWER: 2, AUTHORITY: 0, ADDITIONAL: 1\\n\\n;; QUESTION SECTION:\\n;www.example.com.               IN      A\\n\\n;; ANSWER SECTION:\\nwww.example.com.        300     IN      A       192.0.2.11\\nwww.example.com.        300     IN      A       192.0.2.10\\n\\n;; Query time: 23 msec\\n;; SERVER: 192.0.2.53#53(192.0.2.53) (UDP)\\n;; WHEN: Fri Nov 20 10:00:00 KST 2026\\n;; MSG SIZE  rcvd: 76\\nEOF\\ncat > /tmp/dig_nx.log <<''EOF''\\n; <<>> DiG 9.18.1 <<>> missing.example.com\\n;; Got answer:\\n;; ->>HEADER<<- opcode: QUERY, status: NXDOMAIN, id: 5821\\n;; flags: qr rd ra; QUERY: 1, ANSWER: 0, AUTHORITY: 1, ADDITIONAL: 1\\n\\n;; QUESTION SECTION:\\n;missing.example.com.           IN      A\\n\\n;; AUTHORITY SECTION:\\nexample.com.            900     IN      SOA     ns1.example.net. admin.example.net. 2026112001 7200 900 1209600 86400\\n\\n;; Query time: 31 msec\\n;; SERVER: 192.0.2.53#53(192.0.2.53) (UDP)\\nEOF\\ncat > /tmp/dig_t1.log <<''EOF''\\n;; ANSWER SECTION:\\nwww.example.com.        300     IN      A       192.0.2.10\\n;; Query time: 41 msec\\n;; WHEN: Fri Nov 20 10:00:00 KST 2026\\nEOF\\ncat > /tmp/dig_t2.log <<''EOF''\\n;; ANSWER SECTION:\\nwww.example.com.        240     IN      A       192.0.2.10\\n;; Query time: 0 msec\\n;; WHEN: Fri Nov 20 10:01:00 KST 2026\\nEOF\\ncat > /tmp/dig_trace.log <<''EOF''\\n.                       518400  IN      NS      a.root.example.net.\\n;; Received 239 bytes from 192.0.2.53#53(192.0.2.53) in 1 ms\\n\\ncom.                    172800  IN      NS      a.tld.example.net.\\n;; Received 1170 bytes from 198.51.100.4#53(a.root.example.net) in 12 ms\\n\\nexample.com.            172800  IN      NS      ns1.example.net.\\nexample.com.            172800  IN      NS      ns2.example.net.\\n;; Received 800 bytes from 198.51.100.30#53(a.tld.example.net) in 20 ms\\n\\nwww.example.com.        300     IN      A       192.0.2.10\\n;; Received 60 bytes from 203.0.113.53#53(ns1.example.net) in 25 ms\\nEOF\\ncat > /tmp/resolv_sample.conf <<''EOF''\\nsearch corp.example.com lab.example.com\\nnameserver 192.0.2.53\\nnameserver 192.0.2.54\\noptions ndots:5 timeout:2 attempts:3\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(tr \\"\\\\n\\" \\" \\" < /tmp/ips.txt | xargs)\\" = \\"192.0.2.10 192.0.2.11\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "두 주소가 정렬되어 저장됐다", "cmd": ["sh", "-c", "[ \\"$(tr \\"\\\\n\\" \\" \\" < /tmp/ips.txt | xargs)\\" = \\"192.0.2.10 192.0.2.11\\" ]"]}]', '[{"title": "dig 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/dig.1.html"}, {"title": "resolv.conf 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/resolv.conf.5.html"}]'),
  (570, 3, 'NXDOMAIN 응답 읽기', '`/tmp/dig_nx.log` 는 없는 이름을 질의한 결과입니다. 아래 두 값을 저장하세요. (값만)
- `/tmp/nx_name.txt` : `QUESTION SECTION` 의 질의 이름
- `/tmp/nx_status.txt` : 응답 `status:` 값', '질문 줄은 `;` 로 시작하고 이름이 바로 붙어 있습니다. 상태는 헤더 줄에 있습니다.', 'cat /tmp/dig_nx.log
grep ''^;missing'' /tmp/dig_nx.log | awk ''{print $1}'' | cut -c2- > /tmp/nx_name.txt
grep -o ''status: [A-Z]*'' /tmp/dig_nx.log | cut -d'' '' -f2 > /tmp/nx_status.txt
cat /tmp/nx_name.txt /tmp/nx_status.txt

# NXDOMAIN 은 이름 자체가 없다는 뜻이다. 이름 오타·삭제된 레코드를 먼저 의심한다. ANSWER 가 0 이고 AUTHORITY 에 SOA 가 오는 것이 특징이다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.conf\\ngrep -v ''api.example.com'' /etc/hosts > /tmp/hosts.new; cat /tmp/hosts.new > /etc/hosts; rm -f /tmp/hosts.new\\necho ''192.0.2.77 api.example.com'' >> /etc/hosts\\ncat > /tmp/dig_full.log <<''EOF''\\n; <<>> DiG 9.18.1 <<>> www.example.com\\n;; global options: +cmd\\n;; Got answer:\\n;; ->>HEADER<<- opcode: QUERY, status: NOERROR, id: 41234\\n;; flags: qr rd ra; QUERY: 1, ANSWER: 2, AUTHORITY: 0, ADDITIONAL: 1\\n\\n;; QUESTION SECTION:\\n;www.example.com.               IN      A\\n\\n;; ANSWER SECTION:\\nwww.example.com.        300     IN      A       192.0.2.11\\nwww.example.com.        300     IN      A       192.0.2.10\\n\\n;; Query time: 23 msec\\n;; SERVER: 192.0.2.53#53(192.0.2.53) (UDP)\\n;; WHEN: Fri Nov 20 10:00:00 KST 2026\\n;; MSG SIZE  rcvd: 76\\nEOF\\ncat > /tmp/dig_nx.log <<''EOF''\\n; <<>> DiG 9.18.1 <<>> missing.example.com\\n;; Got answer:\\n;; ->>HEADER<<- opcode: QUERY, status: NXDOMAIN, id: 5821\\n;; flags: qr rd ra; QUERY: 1, ANSWER: 0, AUTHORITY: 1, ADDITIONAL: 1\\n\\n;; QUESTION SECTION:\\n;missing.example.com.           IN      A\\n\\n;; AUTHORITY SECTION:\\nexample.com.            900     IN      SOA     ns1.example.net. admin.example.net. 2026112001 7200 900 1209600 86400\\n\\n;; Query time: 31 msec\\n;; SERVER: 192.0.2.53#53(192.0.2.53) (UDP)\\nEOF\\ncat > /tmp/dig_t1.log <<''EOF''\\n;; ANSWER SECTION:\\nwww.example.com.        300     IN      A       192.0.2.10\\n;; Query time: 41 msec\\n;; WHEN: Fri Nov 20 10:00:00 KST 2026\\nEOF\\ncat > /tmp/dig_t2.log <<''EOF''\\n;; ANSWER SECTION:\\nwww.example.com.        240     IN      A       192.0.2.10\\n;; Query time: 0 msec\\n;; WHEN: Fri Nov 20 10:01:00 KST 2026\\nEOF\\ncat > /tmp/dig_trace.log <<''EOF''\\n.                       518400  IN      NS      a.root.example.net.\\n;; Received 239 bytes from 192.0.2.53#53(192.0.2.53) in 1 ms\\n\\ncom.                    172800  IN      NS      a.tld.example.net.\\n;; Received 1170 bytes from 198.51.100.4#53(a.root.example.net) in 12 ms\\n\\nexample.com.            172800  IN      NS      ns1.example.net.\\nexample.com.            172800  IN      NS      ns2.example.net.\\n;; Received 800 bytes from 198.51.100.30#53(a.tld.example.net) in 20 ms\\n\\nwww.example.com.        300     IN      A       192.0.2.10\\n;; Received 60 bytes from 203.0.113.53#53(ns1.example.net) in 25 ms\\nEOF\\ncat > /tmp/resolv_sample.conf <<''EOF''\\nsearch corp.example.com lab.example.com\\nnameserver 192.0.2.53\\nnameserver 192.0.2.54\\noptions ndots:5 timeout:2 attempts:3\\nEOF\\ntrue"]', '["sh", "-c", "( grep -q \\"^missing.example.com\\" /tmp/nx_name.txt ) && ( [ \\"$(cat /tmp/nx_status.txt)\\" = NXDOMAIN ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "질의 이름이 맞다", "cmd": ["sh", "-c", "grep -q \\"^missing.example.com\\" /tmp/nx_name.txt"]}, {"label": "상태가 NXDOMAIN 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/nx_status.txt)\\" = NXDOMAIN ]"]}]', '[{"title": "dig 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/dig.1.html"}, {"title": "resolv.conf 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/resolv.conf.5.html"}]'),
  (570, 4, '캐시에서 TTL 이 줄어든다', '같은 이름을 한 번 질의하고 한 번 더 질의한 결과가 `/tmp/dig_t1.log`(먼저), `/tmp/dig_t2.log`(나중)에 있습니다. 각 답 레코드의 TTL 은 캐시 서버가 그 레코드를 앞으로 몇 초 더 들고 있을지 알려 줍니다. 두 질의 사이에 **TTL 이 몇 초 줄었는지** 숫자만 `/tmp/elapsed.txt` 에 저장하세요.', '두 질의의 TTL 칸을 각각 뽑아 비교하세요.', 'A=$(grep ''^www'' /tmp/dig_t1.log | awk ''{print $2}'')
B=$(grep ''^www'' /tmp/dig_t2.log | awk ''{print $2}'')
echo $((A - B)) > /tmp/elapsed.txt
cat /tmp/elapsed.txt

# 300 에서 240 으로 60 초 줄었다. 질의 사이에 60 초가 지났고(WHEN 도 1분 차이), 캐시에서 온 응답이라 Query time 이 0 msec 다. TTL 이 0 이 되면 다시 권한 서버에 묻는다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.conf\\ngrep -v ''api.example.com'' /etc/hosts > /tmp/hosts.new; cat /tmp/hosts.new > /etc/hosts; rm -f /tmp/hosts.new\\necho ''192.0.2.77 api.example.com'' >> /etc/hosts\\ncat > /tmp/dig_full.log <<''EOF''\\n; <<>> DiG 9.18.1 <<>> www.example.com\\n;; global options: +cmd\\n;; Got answer:\\n;; ->>HEADER<<- opcode: QUERY, status: NOERROR, id: 41234\\n;; flags: qr rd ra; QUERY: 1, ANSWER: 2, AUTHORITY: 0, ADDITIONAL: 1\\n\\n;; QUESTION SECTION:\\n;www.example.com.               IN      A\\n\\n;; ANSWER SECTION:\\nwww.example.com.        300     IN      A       192.0.2.11\\nwww.example.com.        300     IN      A       192.0.2.10\\n\\n;; Query time: 23 msec\\n;; SERVER: 192.0.2.53#53(192.0.2.53) (UDP)\\n;; WHEN: Fri Nov 20 10:00:00 KST 2026\\n;; MSG SIZE  rcvd: 76\\nEOF\\ncat > /tmp/dig_nx.log <<''EOF''\\n; <<>> DiG 9.18.1 <<>> missing.example.com\\n;; Got answer:\\n;; ->>HEADER<<- opcode: QUERY, status: NXDOMAIN, id: 5821\\n;; flags: qr rd ra; QUERY: 1, ANSWER: 0, AUTHORITY: 1, ADDITIONAL: 1\\n\\n;; QUESTION SECTION:\\n;missing.example.com.           IN      A\\n\\n;; AUTHORITY SECTION:\\nexample.com.            900     IN      SOA     ns1.example.net. admin.example.net. 2026112001 7200 900 1209600 86400\\n\\n;; Query time: 31 msec\\n;; SERVER: 192.0.2.53#53(192.0.2.53) (UDP)\\nEOF\\ncat > /tmp/dig_t1.log <<''EOF''\\n;; ANSWER SECTION:\\nwww.example.com.        300     IN      A       192.0.2.10\\n;; Query time: 41 msec\\n;; WHEN: Fri Nov 20 10:00:00 KST 2026\\nEOF\\ncat > /tmp/dig_t2.log <<''EOF''\\n;; ANSWER SECTION:\\nwww.example.com.        240     IN      A       192.0.2.10\\n;; Query time: 0 msec\\n;; WHEN: Fri Nov 20 10:01:00 KST 2026\\nEOF\\ncat > /tmp/dig_trace.log <<''EOF''\\n.                       518400  IN      NS      a.root.example.net.\\n;; Received 239 bytes from 192.0.2.53#53(192.0.2.53) in 1 ms\\n\\ncom.                    172800  IN      NS      a.tld.example.net.\\n;; Received 1170 bytes from 198.51.100.4#53(a.root.example.net) in 12 ms\\n\\nexample.com.            172800  IN      NS      ns1.example.net.\\nexample.com.            172800  IN      NS      ns2.example.net.\\n;; Received 800 bytes from 198.51.100.30#53(a.tld.example.net) in 20 ms\\n\\nwww.example.com.        300     IN      A       192.0.2.10\\n;; Received 60 bytes from 203.0.113.53#53(ns1.example.net) in 25 ms\\nEOF\\ncat > /tmp/resolv_sample.conf <<''EOF''\\nsearch corp.example.com lab.example.com\\nnameserver 192.0.2.53\\nnameserver 192.0.2.54\\noptions ndots:5 timeout:2 attempts:3\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/elapsed.txt)\\" = 60 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "60 초다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/elapsed.txt)\\" = 60 ]"]}]', '[{"title": "dig 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/dig.1.html"}, {"title": "resolv.conf 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/resolv.conf.5.html"}]'),
  (570, 5, '+trace 의 위임 단계', '`/tmp/dig_trace.log` 는 `dig +trace www.example.com` 의 결과입니다. 루트에서 시작해 한 단계씩 더 아래 서버로 위임을 따라갑니다. 각 단계는 `;; Received` 줄로 끝납니다. 아래 두 값을 저장하세요. (값만)
- `/tmp/steps.txt` : 질의 단계 수 (`;; Received` 줄의 개수)
- `/tmp/auth.txt` : **마지막에 실제 답을 준 서버의 이름** (마지막 `Received` 줄 괄호 안)', '`;; Received` 줄 수를 세고, 마지막 줄에서 서버 이름이 어디에 적혀 있는지 보세요.', 'grep -c '';; Received'' /tmp/dig_trace.log > /tmp/steps.txt
grep '';; Received'' /tmp/dig_trace.log | tail -1 | cut -d''('' -f2 | cut -d'')'' -f1 > /tmp/auth.txt
cat /tmp/steps.txt /tmp/auth.txt

# 루트 → com → example.com 의 권한 서버 → 답. 어느 단계에서 끊기거나 엉뚱한 답이 오는지 위임을 따라가며 확인할 수 있다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.conf\\ngrep -v ''api.example.com'' /etc/hosts > /tmp/hosts.new; cat /tmp/hosts.new > /etc/hosts; rm -f /tmp/hosts.new\\necho ''192.0.2.77 api.example.com'' >> /etc/hosts\\ncat > /tmp/dig_full.log <<''EOF''\\n; <<>> DiG 9.18.1 <<>> www.example.com\\n;; global options: +cmd\\n;; Got answer:\\n;; ->>HEADER<<- opcode: QUERY, status: NOERROR, id: 41234\\n;; flags: qr rd ra; QUERY: 1, ANSWER: 2, AUTHORITY: 0, ADDITIONAL: 1\\n\\n;; QUESTION SECTION:\\n;www.example.com.               IN      A\\n\\n;; ANSWER SECTION:\\nwww.example.com.        300     IN      A       192.0.2.11\\nwww.example.com.        300     IN      A       192.0.2.10\\n\\n;; Query time: 23 msec\\n;; SERVER: 192.0.2.53#53(192.0.2.53) (UDP)\\n;; WHEN: Fri Nov 20 10:00:00 KST 2026\\n;; MSG SIZE  rcvd: 76\\nEOF\\ncat > /tmp/dig_nx.log <<''EOF''\\n; <<>> DiG 9.18.1 <<>> missing.example.com\\n;; Got answer:\\n;; ->>HEADER<<- opcode: QUERY, status: NXDOMAIN, id: 5821\\n;; flags: qr rd ra; QUERY: 1, ANSWER: 0, AUTHORITY: 1, ADDITIONAL: 1\\n\\n;; QUESTION SECTION:\\n;missing.example.com.           IN      A\\n\\n;; AUTHORITY SECTION:\\nexample.com.            900     IN      SOA     ns1.example.net. admin.example.net. 2026112001 7200 900 1209600 86400\\n\\n;; Query time: 31 msec\\n;; SERVER: 192.0.2.53#53(192.0.2.53) (UDP)\\nEOF\\ncat > /tmp/dig_t1.log <<''EOF''\\n;; ANSWER SECTION:\\nwww.example.com.        300     IN      A       192.0.2.10\\n;; Query time: 41 msec\\n;; WHEN: Fri Nov 20 10:00:00 KST 2026\\nEOF\\ncat > /tmp/dig_t2.log <<''EOF''\\n;; ANSWER SECTION:\\nwww.example.com.        240     IN      A       192.0.2.10\\n;; Query time: 0 msec\\n;; WHEN: Fri Nov 20 10:01:00 KST 2026\\nEOF\\ncat > /tmp/dig_trace.log <<''EOF''\\n.                       518400  IN      NS      a.root.example.net.\\n;; Received 239 bytes from 192.0.2.53#53(192.0.2.53) in 1 ms\\n\\ncom.                    172800  IN      NS      a.tld.example.net.\\n;; Received 1170 bytes from 198.51.100.4#53(a.root.example.net) in 12 ms\\n\\nexample.com.            172800  IN      NS      ns1.example.net.\\nexample.com.            172800  IN      NS      ns2.example.net.\\n;; Received 800 bytes from 198.51.100.30#53(a.tld.example.net) in 20 ms\\n\\nwww.example.com.        300     IN      A       192.0.2.10\\n;; Received 60 bytes from 203.0.113.53#53(ns1.example.net) in 25 ms\\nEOF\\ncat > /tmp/resolv_sample.conf <<''EOF''\\nsearch corp.example.com lab.example.com\\nnameserver 192.0.2.53\\nnameserver 192.0.2.54\\noptions ndots:5 timeout:2 attempts:3\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/steps.txt)\\" = 4 ] ) && ( [ \\"$(cat /tmp/auth.txt)\\" = ns1.example.net ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "단계가 4 다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/steps.txt)\\" = 4 ]"]}, {"label": "마지막 서버가 ns1.example.net 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/auth.txt)\\" = ns1.example.net ]"]}]', '[{"title": "dig 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/dig.1.html"}, {"title": "resolv.conf 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/resolv.conf.5.html"}]'),
  (570, 6, '/etc/hosts 가 DNS 를 덮는다', '이 서버의 `/etc/hosts` 에는 이미 한 줄이 들어 있습니다. 응용 프로그램이 이름을 풀 때는 보통 DNS 에 묻기 전에 이 파일부터 봅니다. 시스템이 `api.example.com` 을 **실제로 어떤 주소로 해석하는지** 시스템 해석 도구로 확인해, **주소만** `/tmp/api_ip.txt` 에 저장하세요.', '`dig` 는 hosts 파일을 보지 않습니다. hosts 를 포함한 시스템의 이름 해석 순서를 그대로 따라 조회하는 도구를 찾아 보세요. 순서는 `/etc/nsswitch.conf` 의 `hosts:` 줄에 있습니다.', 'getent hosts api.example.com
getent hosts api.example.com | awk ''{print $1}'' > /tmp/api_ip.txt
cat /tmp/api_ip.txt

# dig 가 DNS 만 묻는 것과 달리 getent 는 nsswitch.conf 의 순서(files → dns)를 따른다. 앱이 보는 결과와 dig 결과가 다르면 hosts 부터 의심한다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.conf\\ngrep -v ''api.example.com'' /etc/hosts > /tmp/hosts.new; cat /tmp/hosts.new > /etc/hosts; rm -f /tmp/hosts.new\\necho ''192.0.2.77 api.example.com'' >> /etc/hosts\\ncat > /tmp/dig_full.log <<''EOF''\\n; <<>> DiG 9.18.1 <<>> www.example.com\\n;; global options: +cmd\\n;; Got answer:\\n;; ->>HEADER<<- opcode: QUERY, status: NOERROR, id: 41234\\n;; flags: qr rd ra; QUERY: 1, ANSWER: 2, AUTHORITY: 0, ADDITIONAL: 1\\n\\n;; QUESTION SECTION:\\n;www.example.com.               IN      A\\n\\n;; ANSWER SECTION:\\nwww.example.com.        300     IN      A       192.0.2.11\\nwww.example.com.        300     IN      A       192.0.2.10\\n\\n;; Query time: 23 msec\\n;; SERVER: 192.0.2.53#53(192.0.2.53) (UDP)\\n;; WHEN: Fri Nov 20 10:00:00 KST 2026\\n;; MSG SIZE  rcvd: 76\\nEOF\\ncat > /tmp/dig_nx.log <<''EOF''\\n; <<>> DiG 9.18.1 <<>> missing.example.com\\n;; Got answer:\\n;; ->>HEADER<<- opcode: QUERY, status: NXDOMAIN, id: 5821\\n;; flags: qr rd ra; QUERY: 1, ANSWER: 0, AUTHORITY: 1, ADDITIONAL: 1\\n\\n;; QUESTION SECTION:\\n;missing.example.com.           IN      A\\n\\n;; AUTHORITY SECTION:\\nexample.com.            900     IN      SOA     ns1.example.net. admin.example.net. 2026112001 7200 900 1209600 86400\\n\\n;; Query time: 31 msec\\n;; SERVER: 192.0.2.53#53(192.0.2.53) (UDP)\\nEOF\\ncat > /tmp/dig_t1.log <<''EOF''\\n;; ANSWER SECTION:\\nwww.example.com.        300     IN      A       192.0.2.10\\n;; Query time: 41 msec\\n;; WHEN: Fri Nov 20 10:00:00 KST 2026\\nEOF\\ncat > /tmp/dig_t2.log <<''EOF''\\n;; ANSWER SECTION:\\nwww.example.com.        240     IN      A       192.0.2.10\\n;; Query time: 0 msec\\n;; WHEN: Fri Nov 20 10:01:00 KST 2026\\nEOF\\ncat > /tmp/dig_trace.log <<''EOF''\\n.                       518400  IN      NS      a.root.example.net.\\n;; Received 239 bytes from 192.0.2.53#53(192.0.2.53) in 1 ms\\n\\ncom.                    172800  IN      NS      a.tld.example.net.\\n;; Received 1170 bytes from 198.51.100.4#53(a.root.example.net) in 12 ms\\n\\nexample.com.            172800  IN      NS      ns1.example.net.\\nexample.com.            172800  IN      NS      ns2.example.net.\\n;; Received 800 bytes from 198.51.100.30#53(a.tld.example.net) in 20 ms\\n\\nwww.example.com.        300     IN      A       192.0.2.10\\n;; Received 60 bytes from 203.0.113.53#53(ns1.example.net) in 25 ms\\nEOF\\ncat > /tmp/resolv_sample.conf <<''EOF''\\nsearch corp.example.com lab.example.com\\nnameserver 192.0.2.53\\nnameserver 192.0.2.54\\noptions ndots:5 timeout:2 attempts:3\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/api_ip.txt)\\" = 192.0.2.77 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "192.0.2.77 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/api_ip.txt)\\" = 192.0.2.77 ]"]}]', '[{"title": "dig 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/dig.1.html"}, {"title": "resolv.conf 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/resolv.conf.5.html"}]'),
  (570, 7, 'resolv.conf 읽기', '`/tmp/resolv_sample.conf` 는 어떤 서버의 `/etc/resolv.conf` 입니다. 이 설정에서 아래 두 값을 저장하세요. (값만)
- `/tmp/ns1.txt` : **가장 먼저 질의하는** DNS 서버 주소
- `/tmp/ndots.txt` : `ndots` 값 (이름에 점이 이 개수보다 적으면 search 도메인을 먼저 붙여 봅니다)', '`nameserver` 줄은 위에서부터 차례로 시도합니다. `options` 줄의 `ndots:` 뒤 숫자를 뽑으세요.', 'cat /tmp/resolv_sample.conf
grep ''^nameserver'' /tmp/resolv_sample.conf | head -1 | awk ''{print $2}'' > /tmp/ns1.txt
grep -o ''ndots:[0-9]*'' /tmp/resolv_sample.conf | cut -d: -f2 > /tmp/ndots.txt
cat /tmp/ns1.txt /tmp/ndots.txt

# ndots:5 면 점이 5개 미만인 이름(www.example.com 도 해당)은 search 도메인을 먼저 붙여 시도해 처음 응답이 느려질 수 있다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.conf\\ngrep -v ''api.example.com'' /etc/hosts > /tmp/hosts.new; cat /tmp/hosts.new > /etc/hosts; rm -f /tmp/hosts.new\\necho ''192.0.2.77 api.example.com'' >> /etc/hosts\\ncat > /tmp/dig_full.log <<''EOF''\\n; <<>> DiG 9.18.1 <<>> www.example.com\\n;; global options: +cmd\\n;; Got answer:\\n;; ->>HEADER<<- opcode: QUERY, status: NOERROR, id: 41234\\n;; flags: qr rd ra; QUERY: 1, ANSWER: 2, AUTHORITY: 0, ADDITIONAL: 1\\n\\n;; QUESTION SECTION:\\n;www.example.com.               IN      A\\n\\n;; ANSWER SECTION:\\nwww.example.com.        300     IN      A       192.0.2.11\\nwww.example.com.        300     IN      A       192.0.2.10\\n\\n;; Query time: 23 msec\\n;; SERVER: 192.0.2.53#53(192.0.2.53) (UDP)\\n;; WHEN: Fri Nov 20 10:00:00 KST 2026\\n;; MSG SIZE  rcvd: 76\\nEOF\\ncat > /tmp/dig_nx.log <<''EOF''\\n; <<>> DiG 9.18.1 <<>> missing.example.com\\n;; Got answer:\\n;; ->>HEADER<<- opcode: QUERY, status: NXDOMAIN, id: 5821\\n;; flags: qr rd ra; QUERY: 1, ANSWER: 0, AUTHORITY: 1, ADDITIONAL: 1\\n\\n;; QUESTION SECTION:\\n;missing.example.com.           IN      A\\n\\n;; AUTHORITY SECTION:\\nexample.com.            900     IN      SOA     ns1.example.net. admin.example.net. 2026112001 7200 900 1209600 86400\\n\\n;; Query time: 31 msec\\n;; SERVER: 192.0.2.53#53(192.0.2.53) (UDP)\\nEOF\\ncat > /tmp/dig_t1.log <<''EOF''\\n;; ANSWER SECTION:\\nwww.example.com.        300     IN      A       192.0.2.10\\n;; Query time: 41 msec\\n;; WHEN: Fri Nov 20 10:00:00 KST 2026\\nEOF\\ncat > /tmp/dig_t2.log <<''EOF''\\n;; ANSWER SECTION:\\nwww.example.com.        240     IN      A       192.0.2.10\\n;; Query time: 0 msec\\n;; WHEN: Fri Nov 20 10:01:00 KST 2026\\nEOF\\ncat > /tmp/dig_trace.log <<''EOF''\\n.                       518400  IN      NS      a.root.example.net.\\n;; Received 239 bytes from 192.0.2.53#53(192.0.2.53) in 1 ms\\n\\ncom.                    172800  IN      NS      a.tld.example.net.\\n;; Received 1170 bytes from 198.51.100.4#53(a.root.example.net) in 12 ms\\n\\nexample.com.            172800  IN      NS      ns1.example.net.\\nexample.com.            172800  IN      NS      ns2.example.net.\\n;; Received 800 bytes from 198.51.100.30#53(a.tld.example.net) in 20 ms\\n\\nwww.example.com.        300     IN      A       192.0.2.10\\n;; Received 60 bytes from 203.0.113.53#53(ns1.example.net) in 25 ms\\nEOF\\ncat > /tmp/resolv_sample.conf <<''EOF''\\nsearch corp.example.com lab.example.com\\nnameserver 192.0.2.53\\nnameserver 192.0.2.54\\noptions ndots:5 timeout:2 attempts:3\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/ns1.txt)\\" = 192.0.2.53 ] ) && ( [ \\"$(cat /tmp/ndots.txt)\\" = 5 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "첫 서버가 192.0.2.53 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/ns1.txt)\\" = 192.0.2.53 ]"]}, {"label": "ndots 가 5 다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/ndots.txt)\\" = 5 ]"]}]', '[{"title": "dig 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/dig.1.html"}, {"title": "resolv.conf 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/resolv.conf.5.html"}]'),
  (570, 8, 'NOERROR 인데 답이 없다', 'dig 결과가 `status: NOERROR` 인데 `ANSWER: 0` 입니다. (질의한 것은 AAAA 레코드이고, 같은 이름의 A 레코드는 정상적으로 풀립니다) 가장 알맞은 해석은?', 'NXDOMAIN 과 무엇이 다른지 생각해 보세요.', NULL, NULL, '[]', 'choice', '["이름 자체가 존재하지 않는다", "이름은 있지만 요청한 타입의 레코드가 없다", "DNS 서버가 응답하지 못하고 시간 초과됐다", "캐시 서버가 질의를 거부했다"]', 1, 'NOERROR 는 이름이 존재한다는 뜻이고 답이 비어 있으면 그 이름에 요청한 타입의 레코드만 없는 것입니다. 이름 자체가 없으면 NXDOMAIN, 서버가 거부하면 REFUSED, 응답이 없으면 dig 가 시간 초과를 보여 줍니다.', NULL, NULL, NULL, NULL),
  (570, 9, '루트부터 위임을 따라가는 옵션', '캐시 서버의 답이 아닌 **루트부터 권한 서버까지 위임을 한 단계씩 따라가며** 보여 주는 dig 옵션을 채우세요. 어느 단계에서 끊기는지 찾을 때 씁니다.', '`dig` 의 `+` 로 시작하는 질의 옵션 중 하나입니다.', NULL, NULL, '[]', 'fill', '["trace", "short", "tcp", "norecurse"]', NULL, '`+trace` 는 루트 서버부터 시작해 위임을 따라가며 각 단계의 응답을 보여 줍니다. `+short` 는 답만 짧게 출력하고, `+tcp` 는 UDP 대신 TCP 로 질의하며, `+norecurse` 는 서버에 재귀 질의를 요청하지 않는 옵션입니다.', '[0]', 'dig +{0} www.example.com', NULL, NULL),
  (570, 10, '이름이 안 풀릴 때 점검 순서', '앱이 `api.example.com` 을 찾지 못합니다. 가까운 곳에서 먼 곳으로 범위를 좁혀 가며 원인을 찾으려 합니다. 앞 단계의 결과가 다음 단계에서 무엇을 볼지 정해 주는 순서로 놓으세요. 앱이 보는 최종 결과를 먼저 확인하고, 마지막에는 어느 서버·어느 위임 단계에서 끊기는지 따라갑니다.', '다음 단계에서 누구에게 물을지는 앞 단계에서 알게 됩니다.', NULL, NULL, '[]', 'order', '["`/etc/resolv.conf` 에서 확인한 그 서버에 `dig @서버 이름` 으로 직접 질의해 답하는지 확인", "`dig +trace 이름` 으로 어느 위임 단계에서 끊기는지 확인", "`getent hosts 이름` 으로 시스템이 실제로 어떻게 해석하는지 확인", "`/etc/resolv.conf` 로 어느 DNS 서버에 묻도록 되어 있는지 확인"]', NULL, '시스템 해석 결과(hosts 포함)를 먼저 보고, 설정된 서버를 확인한 뒤, 그 서버에 직접 질의하고, 마지막에 위임을 따라가며 상위 단계의 문제를 찾습니다. 앞 단계에서 원인이 나오면 뒤 단계는 필요 없습니다.', '[2, 3, 0, 1]', NULL, NULL, NULL);
